import re
import logging
from typing import Optional
from functools import wraps

def setup_logging(name: str, level: int = logging.INFO) -> logging.Logger:
    logger = logging.getLogger(name)
    logger.setLevel(level)

    if not logger.handlers:
        handler = logging.StreamHandler()
        formatter = logging.Formatter(
            '%(asctime)s - %(name)s - %(levelname)s - %(message)s'
        )
        handler.setFormatter(formatter)
        logger.addHandler(handler)

    return logger

def validate_input(value: str, pattern: str, max_length: int = 255) -> bool:
    """Validate input against a regex pattern."""
    if not value or len(value) > max_length:
        return False
    return bool(re.match(pattern, value))

def sanitize_output(data: dict, sensitive_keys: list = None) -> dict:
    """Remove sensitive keys from output dictionary."""
    if sensitive_keys is None:
        sensitive_keys = ['password', 'secret', 'key', 'token', 'api_key']

    result = {}
    for k, v in data.items():
        if any(sens in k.lower() for sens in sensitive_keys):
            result[k] = '[REDACTED]'
        elif isinstance(v, dict):
            result[k] = sanitize_output(v, sensitive_keys)
        else:
            result[k] = v
    return result
