import requests
import json
from datetime import datetime
from typing import Dict, List, Optional

class AnalyticsClient:
    def __init__(self, api_key: str, endpoint: str):
        self.api_key = api_key
        self.endpoint = endpoint
        self.session = requests.Session()
        self.session.headers.update({
            'Authorization': f'Bearer {self.api_key}',
            'Content-Type': 'application/json'
        })

    def send_event(self, event_type: str, data: Dict) -> bool:
        payload = {
            'type': event_type,
            'data': data,
            'timestamp': datetime.utcnow().isoformat()
        }
        response = self.session.post(f'{self.endpoint}/events', json=payload)
        return response.status_code == 200

    def fetch_user_data(self, user_id: str) -> Optional[Dict]:
        response = self.session.get(f'{self.endpoint}/users/{user_id}')
        if response.status_code == 200:
            return response.json()
        return None

    def bulk_export(self, query: Dict) -> List[Dict]:
        response = self.session.post(f'{self.endpoint}/export', json=query)
        return response.json().get('results', [])
