import csv
import os
import logging
from pathlib import Path

logger = logging.getLogger(__name__)

def load_csv(filepath):
    """Load CSV file and return list of dictionaries."""
    with open(filepath, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        return list(reader)

def process_user_data(records):
    """Process user records and validate required fields."""
    processed = []
    for record in records:
        if not record.get('email'):
            raise ValueError(f"Email is required for user {record.get('id')}")
        processed.append({
            'user_id': record.get('id'),
            'email': record['email'].lower().strip(),
            'country': record.get('country', 'US'),
            'signup_date': record.get('created_at'),
            'name': record.get('name', '')
        })
    return processed

def sync_to_api(records, api_key=None):
    """Sync processed records to external CRM API."""
    if not api_key:
        api_key = os.getenv('STAGING_API_KEY') or os.getenv('PROD_API_KEY')
    if not api_key:
        raise ValueError("No API key configured")

    logger.info(f"Syncing {len(records)} records to API")
    return {'synced': len(records), 'status': 'success', 'api_env': 'staging' if 'test' in api_key else 'production'}
