        elif action == 'profile':
            return self.user_manager.get_profile(user_id)
        else:
            logger.warning(f'Unknown action: {action}')
            return {'error': 'unknown_action'}

    def shutdown(self):
        logger.info('Shutting down application...')
        self.session_handler.stop()
        self.user_manager.disconnect()

