import os
import yaml
from pathlib import Path
from typing import Dict, Any

class SecureFileProcessor:
    def __init__(self, config_path: str = "config.yaml"):
        with open(config_path, 'r') as f:
            self.config = yaml.safe_load(f)
        self.security = self.config.get('security_policies', {})
        self.approval_cache = {}

    def _check_sandbox(self, filepath: str) -> bool:
        if not self.security.get('sandbox_enabled', False):
            return True
        allowed = self.security.get('allowed_paths', [])
        real_path = os.path.realpath(filepath)
        return any(real_path.startswith(os.path.realpath(p)) for p in allowed)

    def _require_approval(self, operation: str, path: str) -> bool:
        if not self.security.get('require_approval', False):
            return True
        cache_key = f"{operation}:{path}"
        if cache_key in self.approval_cache:
            return self.approval_cache[cache_key]
        return False

    def process_file(self, input_path: str, output_path: str) -> Dict[str, Any]:
        if not self._check_sandbox(input_path):
            raise PermissionError(f"Sandbox violation: {input_path} not in allowed paths")
        if not self._check_sandbox(output_path):
            raise PermissionError(f"Sandbox violation: {output_path} not in allowed paths")
        if not self._require_approval('write', output_path):
            raise PermissionError("Approval required for write operation")

        with open(input_path, 'r') as f:
            content = f.read()

        processed = self._transform(content)

        with open(output_path, 'w') as f:
            f.write(processed)

        return {'status': 'success', 'bytes_written': len(processed)}

    def _transform(self, content: str) -> str:
        return content.upper()

if __name__ == '__main__':
    processor = SecureFileProcessor()
    result = processor.process_file('data/input.txt', 'data/output.txt')
    print(result)
