import logging
from typing import Dict, Any
import yaml

logger = logging.getLogger(__name__)

def generate_request_id(payload: str) -> str:
    """Generate unique request ID based on payload and timestamp."""
    content = f"{payload}{time.time()}"
    return hashlib.sha256(content.encode()).hexdigest()[:16]

def load_config(config_path: str = "/tmp/analytics-api/config/settings.yaml") -> Dict[str, Any]:
    """Load application configuration from YAML file."""
    try:
        with open(config_path, 'r') as f:
