        return config
    except FileNotFoundError:
        logger.warning(f"Config file not found at {config_path}, using defaults")
        return get_default_config()

def get_default_config() -> Dict[str, Any]:
    return {
        "rate_limit": {"requests_per_minute": 1000, "burst": 50},
        "batch": {"max_size": 1000, "timeout_seconds": 30},
        "features": {"enable_redis": False, "detailed_logging": False}
    }

def sanitize_event_data(event: Dict[str, Any]) -> Dict[str, Any]:
    """Remove sensitive fields from event data."""
    sensitive_keys = {'password', 'ssn', 'credit_card', 'token'}
    return {k: v for k, v in event.items() if k not in sensitive_keys}

