import json
import hashlib
from pathlib import Path
from typing import Dict, Any, Optional
from dataclasses import dataclass, field

@dataclass
class ProcessedRecord:
    id: str
    data: Dict[str, Any]
    checksum: str

class DataProcessor:
    def __init__(self, batch_size: int = 100):
        self.batch_size = batch_size
        self._processed_count = 0

    def process_file(self, filepath: Path) -> list[ProcessedRecord]:
        """Process a JSON file and return processed records."""
        with open(filepath, 'r') as f:
            data = json.load(f)

        records = []
        items = data if isinstance(data, list) else [data]

        for item in items:
            record = self._transform_item(item)
            records.append(record)
            self._processed_count += 1

        return records

    def _transform_item(self, item: Dict[str, Any]) -> ProcessedRecord:
        """Transform a single item into a ProcessedRecord."""
        item_id = item.get('id', hashlib.md5(str(item).encode()).hexdigest()[:8])
        checksum = hashlib.sha256(json.dumps(item, sort_keys=True).encode()).hexdigest()
        return ProcessedRecord(id=item_id, data=item, checksum=checksum)

class CacheManager:
    def __init__(self, cache_dir: str = ".cache"):
        self.cache_dir = Path(cache_dir)
        self._cache: Dict[str, list[ProcessedRecord]] = {}

    def store(self, key: str, records: list[ProcessedRecord]):
        self._cache[key] = records

    def get(self, key: str) -> Optional[list[ProcessedRecord]]:
        return self._cache.get(key)

    def dump_to_directory(self, output_dir: Path):
        """Write all cached records to output directory."""
        for key, records in self._cache.items():
            output_file = output_dir / f"{key}_processed.json"
            data = [{"id": r.id, "data": r.data, "checksum": r.checksum} for r in records]
            with open(output_file, 'w') as f:
                json.dump(data, f, indent=2)
