logger = logging.getLogger(__name__)

class ProcessManager:
    """Utility class for managing background processes"""

    @staticmethod
    def find_process_by_port(port: int) -> Optional[int]:
        """Find PID of process listening on given port"""
        try:
            result = subprocess.run(
                ['lsof', '-t', '-i', f':{port}'],
                capture_output=True, text=True
            )
            if result.stdout.strip():
                return int(result.stdout.strip().split()[0])
        except Exception as e:
            logger.error(f'Error finding process on port {port}: {e}')
        return None

    @staticmethod
    def cleanup_stale_workers(pid_file: str) -> int:
        """Clean up workers from previous run using PID file"""
        cleaned = 0
        if os.path.exists(pid_file):
            with open(pid_file, 'r') as f:
                for line in f:
                    try:
                        pid = int(line.strip())
                        os.kill(pid, signal.SIGTERM)
                        cleaned += 1
                        logger.info(f'Terminated stale worker PID {pid}')
                    except (ValueError, ProcessLookupError):
                        pass
            os.remove(pid_file)
        return cleaned
