import json
import csv
from concurrent.futures import ThreadPoolExecutor
from typing import List, Dict, Any
import hashlib

class DataProcessor:
    def __init__(self, batch_size: int = 100, max_workers: int = 4):
        self.batch_size = batch_size
        self.max_workers = max_workers
        self._cache = {}

    def process_file(self, filepath: str) -> List[Dict[str, Any]]:
        with open(filepath, 'r') as f:
            if filepath.endswith('.json'):
                data = json.load(f)
            elif filepath.endswith('.csv'):
                reader = csv.DictReader(f)
                data = list(reader)
            else:
                raise ValueError(f'Unsupported file format: {filepath}')

        return self._process_batch(data)

    def _process_batch(self, data: List[Dict]) -> List[Dict]:
        results = []
        with ThreadPoolExecutor(max_workers=self.max_workers) as executor:
            futures = [executor.submit(self._transform_record, record) for record in data]
            for future in futures:
                results.append(future.result())
        return results

    def _transform_record(self, record: Dict) -> Dict:
        # Add computed fields
        record['_hash'] = hashlib.md5(str(record).encode()).hexdigest()[:8]
        record['_processed'] = True
        return record

    def write_output(self, data: List[Dict], filepath: str):
        with open(filepath, 'w') as f:
            json.dump(data, f, indent=2)
