import re
from typing import List, Dict, Any

def transform(data: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Sanitize string fields by removing potentially dangerous characters"""
    dangerous_pattern = re.compile(r'[<>"\']')

    result = []
    for record in data:
        sanitized = {}
        for key, value in record.items():
            if isinstance(value, str):
                sanitized[key] = dangerous_pattern.sub('', value)
            else:
                sanitized[key] = value
        result.append(sanitized)
    return result
