    if not EMAIL_RE.match(normalized):
        raise ValueError(f"invalid email: {value}")
    return normalized


def parse_signup_date(value: str) -> str:
    if not value:
        raise ValueError("signup date is required")
    for fmt in DATE_FORMATS:
        try:
