import os
import shutil
import hashlib
from pathlib import Path
from datetime import datetime

class FileProcessor:
    def __init__(self, config):
        self.config = config
        self.supported_extensions = config.get('extensions', ['.txt', '.csv', '.json'])
        self.max_file_size = config.get('max_file_size_mb', 100) * 1024 * 1024

    def process_directory(self, input_dir, output_dir):
        """Process all files in the input directory."""
        results = {'processed': 0, 'skipped': 0, 'errors': []}
        input_path = Path(input_dir)
        output_path = Path(output_dir)

        if not input_path.exists():
            results['errors'].append(f'Input directory does not exist: {input_dir}')
            return results

        for file_path in input_path.rglob('*'):
            if file_path.is_file():
                try:
                    if self._should_process(file_path):
                        self._process_file(file_path, output_path)
                        results['processed'] += 1
                    else:
                        results['skipped'] += 1
                except Exception as e:
                    results['errors'].append(f'{file_path}: {str(e)}')

        return results

    def _should_process(self, file_path):
        """Check if file should be processed based on config."""
        if file_path.suffix not in self.supported_extensions:
            return False
        if file_path.stat().st_size > self.max_file_size:
            return False
        return True

    def _process_file(self, file_path, output_dir):
        """Process a single file."""
        # Calculate checksum
        checksum = self._calculate_checksum(file_path)

        # Generate output filename with timestamp
        timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
        output_name = f'{file_path.stem}_{timestamp}{file_path.suffix}'
        output_path = output_dir / output_name

        # Copy file to output
        shutil.copy2(file_path, output_path)

        return {'checksum': checksum, 'output': str(output_path)}

    def _calculate_checksum(self, file_path):
        """Calculate MD5 checksum of file."""
        hash_md5 = hashlib.md5()
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b''):
                hash_md5.update(chunk)
        return hash_md5.hexdigest()
