    text = config_path.read_text()
    if config_path.suffix in {'.yaml', '.yml'}:
        if yaml is None:
            raise RuntimeError('PyYAML is required to load YAML config files')
        return yaml.safe_load(text)
    if config_path.suffix == '.json':
