import sqlite3
from datetime import datetime
from config import Config

class BaseModel:
    _connection = None

    @classmethod
    def get_connection(cls):
        if cls._connection is None:
            cls._connection = sqlite3.connect(Config.DATABASE_PATH)
        return cls._connection

class UserModel(BaseModel):
    def __init__(self, id, username, email, created_at):
        self.id = id
        self.username = username
        self.email = email
        self.created_at = created_at

    def to_dict(self):
        return {
            'id': self.id,
            'username': self.username,
            'email': self.email,
            'created_at': self.created_at.isoformat() if isinstance(self.created_at, datetime) else self.created_at
        }

    @classmethod
    def get_by_id(cls, user_id):
        conn = cls.get_connection()
        cursor = conn.cursor()
        cursor.execute('SELECT id, username, email, created_at FROM users WHERE id = ?', (user_id,))
        row = cursor.fetchone()
        if row:
            return cls(*row)
        return None

    @classmethod
    def get_paginated(cls, page=1, limit=20):
        conn = cls.get_connection()
        cursor = conn.cursor()
        offset = (page - 1) * limit
        cursor.execute('SELECT id, username, email, created_at FROM users LIMIT ? OFFSET ?', (limit, offset))
        return [cls(*row).to_dict() for row in cursor.fetchall()]

    @classmethod
    def count(cls):
        conn = cls.get_connection()
        cursor = conn.cursor()
        cursor.execute('SELECT COUNT(*) FROM users')
        return cursor.fetchone()[0]

class SessionModel(BaseModel):
    def __init__(self, id, user_id, token, metadata, created_at):
        self.id = id
        self.user_id = user_id
        self.token = token
        self.metadata = metadata
        self.created_at = created_at

    def to_dict(self):
        return {
            'id': self.id,
            'user_id': self.user_id,
            'token': self.token,
            'metadata': self.metadata,
            'created_at': self.created_at
        }

    @classmethod
    def create(cls, user_id, metadata=None):
        import secrets
        conn = cls.get_connection()
        cursor = conn.cursor()
        token = secrets.token_urlsafe(32)
        created_at = datetime.utcnow().isoformat()
        cursor.execute(
            'INSERT INTO sessions (user_id, token, metadata, created_at) VALUES (?, ?, ?, ?)',
            (user_id, token, str(metadata or {}), created_at)
        )
        conn.commit()
        return cls(cursor.lastrowid, user_id, token, metadata, created_at)
