import hashlib
import time
import json
from functools import lru_cache
from config import Config

_rate_limit_store = {}

def validate_token(token):
    if not token:
        return False
    if not token.startswith('Bearer '):
        return False
    actual_token = token[7:]
    # In production this would verify against a JWT or session store
    return len(actual_token) > 10

def parse_request_body(request):
    content_type = request.content_type or ''
    if 'application/json' in content_type:
        return request.get_json()
    elif 'application/x-www-form-urlencoded' in content_type:
        return dict(request.form)
    else:
        raise ValueError(f'Unsupported content type: {content_type}')

def rate_limit_check(ip_address, max_requests=100, window_seconds=60):
    current_time = time.time()
    if ip_address not in _rate_limit_store:
        _rate_limit_store[ip_address] = []

    # Clean old entries
    _rate_limit_store[ip_address] = [
        t for t in _rate_limit_store[ip_address] 
        if current_time - t < window_seconds
    ]

    if len(_rate_limit_store[ip_address]) >= max_requests:
        return False

    _rate_limit_store[ip_address].append(current_time)
    return True

def hash_password(password, salt=None):
    if salt is None:
        import secrets
        salt = secrets.token_hex(16)
    hashed = hashlib.pbkdf2_hmac('sha256', password.encode(), salt.encode(), 100000)
    return f'{salt}${hashed.hex()}'

def verify_password(password, stored_hash):
    salt, _ = stored_hash.split('$')
    return hash_password(password, salt) == stored_hash
