import datetime
import hashlib
from dataclasses import dataclass, field
from typing import Optional

@dataclass
class User:
    email: str
    password_hash: str
    id: Optional[int] = None
    created_at: datetime.datetime = field(default_factory=datetime.datetime.utcnow)
    is_active: bool = True

    def verify_password(self, password: str) -> bool:
        return hashlib.sha256(password.encode()).hexdigest() == self.password_hash

    def to_dict(self):
        return {
            'id': self.id,
            'email': self.email,
            'created_at': self.created_at.isoformat(),
            'is_active': self.is_active
        }

@dataclass
class Session:
    user_id: int
    token: str
    id: Optional[int] = None
    created_at: datetime.datetime = field(default_factory=datetime.datetime.utcnow)
    expires_at: datetime.datetime = field(default_factory=lambda: datetime.datetime.utcnow() + datetime.timedelta(hours=24))

    def is_expired(self) -> bool:
        return datetime.datetime.utcnow() > self.expires_at

class DatabaseConnection:
    def __init__(self, connection_url: str):
        self.connection_url = connection_url
        self._connection = None
        self._cache = {}

    def connect(self):
        # Simulate database connection
        print(f"Connecting to {self.connection_url}")
        self._connection = True

    def save(self, obj):
        if obj.id is None:
            obj.id = len(self._cache) + 1
        self._cache[obj.id] = obj
        return obj

    def query(self, model_class):
        return QueryBuilder(self._cache, model_class)

class QueryBuilder:
    def __init__(self, cache, model_class):
        self._cache = cache
        self._model_class = model_class
        self._filters = {}

    def filter_by(self, **kwargs):
        self._filters = kwargs
        return self

    def first(self):
        for obj in self._cache.values():
            if isinstance(obj, self._model_class):
                match = all(getattr(obj, k, None) == v for k, v in self._filters.items())
                if match:
                    return obj
        return None
