"""Advanced calculator module with statistical functions and precision handling."""

from typing import List, Dict, Any
from decimal import Decimal, ROUND_HALF_UP

class Calculator:
    """Scientific calculator with history tracking."""

    def __init__(self, precision: int = 2):
        self.precision = precision
        self.history: List[Dict[str, Any]] = []
        self._decimal_places = Decimal(10) ** -precision

    def add(self, a: float, b: float) -> float:
        """Add two numbers with precision rounding."""
        result = Decimal(str(a)) + Decimal(str(b))
        rounded = float(result.quantize(self._decimal_places, rounding=ROUND_HALF_UP))
        self.history.append({"op": "add", "args": [a, b], "result": rounded})
        return rounded

    def divide(self, a: float, b: float) -> float:
        """Safe division with zero checking."""
        if b == 0:
            raise ValueError("Division by zero is undefined")
        if a == 0:
            return 0.0
        result = Decimal(str(a)) / Decimal(str(b))
        rounded = float(result.quantize(self._decimal_places, rounding=ROUND_HALF_UP))
        self.history.append({"op": "divide", "args": [a, b], "result": rounded})
        return rounded

    def get_stats(self) -> Dict[str, int]:
        """Return operation statistics."""
        return {
            "total_ops": len(self.history),
            "additions": sum(1 for h in self.history if h["op"] == "add"),
            "divisions": sum(1 for h in self.history if h["op"] == "divide")
        }

def calculate_mean(values: List[float]) -> float:
    """Calculate arithmetic mean with empty list protection."""
    if not values:
        return 0.0
    return sum(values) / len(values)

def calculate_std_dev(values: List[float]) -> float:
    """Calculate population standard deviation."""
    if len(values) < 2:
        return 0.0
    mean = calculate_mean(values)
    variance = sum((x - mean) ** 2 for x in values) / len(values)
    return variance ** 0.5
