import re
import time
from typing import Dict, Any, Optional
from functools import lru_cache
import hashlib

# Simple in-memory rate limiter
_rate_limit_store: Dict[str, list] = {}
RATE_LIMIT_WINDOW = 60  # seconds
RATE_LIMIT_MAX = 100  # requests per window

def validate_token(token: Optional[str]) -> bool:
    if not token:
        return False
    if not token.startswith('Bearer '):
        return False
    jwt_part = token[7:]
    # Basic JWT structure check (header.payload.signature)
    parts = jwt_part.split('.')
    return len(parts) == 3 and all(len(p) > 0 for p in parts)

def rate_limit_check(ip_address: str) -> bool:
    current_time = time.time()
    if ip_address not in _rate_limit_store:
        _rate_limit_store[ip_address] = []

    # Clean old entries
    _rate_limit_store[ip_address] = [
        t for t in _rate_limit_store[ip_address]
        if current_time - t < RATE_LIMIT_WINDOW
    ]

    if len(_rate_limit_store[ip_address]) >= RATE_LIMIT_MAX:
        return False

    _rate_limit_store[ip_address].append(current_time)
    return True

def sanitize_input(data: Dict[str, Any]) -> Dict[str, Any]:
    sanitized = {}
    for key, value in data.items():
        if isinstance(value, str):
            # Remove potential XSS vectors
            value = re.sub(r'<[^>]*>', '', value)
            value = value.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;')
        sanitized[key] = value
    return sanitized

@lru_cache(maxsize=1000)
def hash_password(password: str, salt: str) -> str:
    return hashlib.pbkdf2_hmac('sha256', password.encode(), salt.encode(), 100000).hex()
