def validate_input(data, required_fields):
    """Validate that all required fields are present and non-empty."""
    if not isinstance(data, dict):
        return False
    for field in required_fields:
        if field not in data or not data[field]:
            return False
    return True

def sanitize_output(text):
    """Remove potentially dangerous characters from user input."""
    if not isinstance(text, str):
        return text
    # Remove script tags and SQL injection attempts
    text = re.sub(r'<script[^>]*>.*?</script>', '', text, flags=re.IGNORECASE | re.DOTALL)
    text = re.sub(r"[;'\"--]", '', text)
    return text.strip()

def rate_limit(requests_per_minute=60):
    """Decorator to rate limit API endpoints."""
    def decorator(f):
        @functools.wraps(f)
        def wrapped(*args, **kwargs):
            client_ip = request.remote_addr
            now = time.time()

            # Clean old entries
            _rate_limit_storage[client_ip] = [
                t for t in _rate_limit_storage[client_ip]
                if now - t < 60
            ]

            if len(_rate_limit_storage[client_ip]) >= requests_per_minute:
                return jsonify({'error': 'Rate limit exceeded'}), 429

            _rate_limit_storage[client_ip].append(now)
            return f(*args, **kwargs)
        return wrapped
    return decorator

def format_error_response(message, status_code=400):
    """Standard error response format."""
    return jsonify({
        'error': True,
        'message': message,
        'status_code': status_code
    }), status_code
