import psycopg2
from psycopg2 import pool
import yaml
import os
import logging

logger = logging.getLogger(__name__)

class DatabasePool:
    _instance = None
    _pool = None

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
            cls._initialize_pool()
        return cls._instance

    @classmethod
    def _initialize_pool(cls):
        try:
            with open('/home/user/inventory-service/config.yaml', 'r') as f:
                config = yaml.safe_load(f)

            db_config = config['database']
            cls._pool = psycopg2.pool.ThreadedConnectionPool(
                minconn=2,
                maxconn=5,  # Insufficient for production load - causes exhaustion
                host=db_config['host'],
                port=db_config['port'],
                database=db_config['name'],
                user=db_config['user'],
                password=os.environ.get('DB_PASSWORD', db_config.get('password', ''))
            )
            logger.info("Database pool initialized with max 5 connections")
        except Exception as e:
            logger.error(f"Failed to initialize database pool: {e}")
            raise

    @classmethod
    def get_connection(cls):
        if cls._pool is None:
            DatabasePool()
        try:
            conn = cls._pool.getconn()
            logger.debug(f"Connection acquired. Pool usage: {cls._pool.nused}/{cls._pool.maxconn}")
            return conn
        except psycopg2.pool.PoolError as e:
            logger.error(f"Connection pool exhausted: {e}")
            raise

    @classmethod
    def return_connection(cls, conn):
        if cls._pool and conn:
            cls._pool.putconn(conn)
            logger.debug("Connection returned to pool")
