from __future__ import annotations

from datetime import datetime, timezone
from decimal import Decimal, InvalidOperation
from typing import Iterable, Dict, Any, List


def parse_price(value: str) -> Decimal:
    """Parse a price string like '12.50' or '$12.50'."""
    cleaned = value.strip().replace('$', '').replace(',', '')
    try:
        return Decimal(cleaned)
    except InvalidOperation as exc:
        raise ValueError(f"invalid price: {value}") from exc


def normalize_sku(raw: str) -> str:
    return raw.strip().upper().replace(' ', '-')


def utc_now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


def summarize_inventory(items: Iterable[Dict[str, Any]]) -> Dict[str, Any]:
    rows: List[Dict[str, Any]] = list(items)
    total_items = len(rows)
    total_quantity = sum(int(row.get('quantity', 0)) for row in rows)
    total_value = sum(parse_price(str(row.get('price', '0'))) * int(row.get('quantity', 0)) for row in rows)
    low_stock = [row['sku'] for row in rows if int(row.get('quantity', 0)) < 5]
    return {
        'total_items': total_items,
        'total_quantity': total_quantity,
        'total_value': str(total_value),
        'low_stock': low_stock,
    }
