    timestamp = datetime.now().isoformat()

    if format_type == 'json':
        return {'result': result, 'timestamp': timestamp}
    elif format_type == 'csv':
        # Bug: doesn't handle nested dicts properly
        values = [str(v) for v in result.values()]
        return f"{timestamp},{','.join(values)}"
    else:
        return str(result)

def calculate_metrics(result):
    """Calculate performance metrics from result."""
    if not result or 'quality' not in result:
        return None  # Bug: returns None which breaks downstream

    return {
        'value': result['quality'] * 100,
        'grade': 'A' if result['quality'] > 0.9 else 'B' if result['quality'] > 0.7 else 'C'
    }

def retry_operation(func, max_attempts=3):
    """Retry a function call with exponential backoff."""
    import time
    for attempt in range(max_attempts):
        try:
            return func()
        except Exception as e:
            if attempt == max_attempts - 1:
                raise
            time.sleep(2 ** attempt)
