import json
from typing import Dict, List, Any, Optional
from pathlib import Path


class DataProcessor:
    """Process and transform data from various sources."""

    def __init__(self):
        self.data = []
        self.processed_count = 0

    def load_json(self, filepath: str) -> List[Dict]:
        """Load data from a JSON file."""
        path = Path(filepath)
        if not path.exists():
            raise FileNotFoundError(f"File not found: {filepath}")
        with open(path, 'r') as f:
            self.data = json.load(f)
        return self.data

    def filter_by_field(self, field: str, value: Any) -> List[Dict]:
        """Filter data by a specific field value."""
        return [item for item in self.data if item.get(field) == value]

    def sort_by_field(self, field: str, reverse: bool = False) -> List[Dict]:
        """Sort data by a specific field."""
        return sorted(self.data, key=lambda x: x.get(field, ''), reverse=reverse)

    def aggregate(self, field: str) -> Dict[Any, int]:
        """Count occurrences of each unique value in a field."""
        counts = {}
        for item in self.data:
            key = item.get(field)
            counts[key] = counts.get(key, 0) + 1
        return counts

    def transform(self, transformer: callable) -> List[Dict]:
        """Apply a transformation function to each item."""
        self.data = [transformer(item) for item in self.data]
        self.processed_count += len(self.data)
        return self.data

    def export_json(self, filepath: str, indent: int = 2) -> None:
        """Export data to a JSON file."""
        with open(filepath, 'w') as f:
            json.dump(self.data, f, indent=indent)
