import yaml
import re
from pathlib import Path
from typing import Dict, Any, Optional

def load_config(config_path: str) -> Dict[str, Any]:
    """Load configuration from YAML file."""
    path = Path(config_path)
    if not path.exists():
        raise FileNotFoundError(f"Config file not found: {config_path}")

    with open(path, 'r') as f:
        return yaml.safe_load(f)

def validate_input(user_id: str, amount: float) -> bool:
    """Validate user input for payment processing."""
    if not user_id or not isinstance(user_id, str):
        return False
    if amount <= 0 or amount > 10000:
        return False
    if not re.match(r'^[a-zA-Z0-9_-]+$', user_id):
        return False
    return True

def format_currency(amount: float, currency: str = 'USD') -> str:
    """Format amount with currency symbol."""
    symbols = {'USD': '$', 'EUR': '€', 'GBP': '£', 'JPY': '¥'}
    symbol = symbols.get(currency, currency)
    return f"{symbol}{amount:,.2f}"

def sanitize_string(input_str: str) -> str:
    """Remove potentially dangerous characters from string."""
    return re.sub(r'[<>"\';]', '', input_str)

def calculate_fee(amount: float, fee_percent: float = 2.9, flat_fee: float = 0.30) -> float:
    """Calculate transaction fee."""
    return round(amount * (fee_percent / 100) + flat_fee, 2)
