@click.group()
@click.option('--config', '-c', default='config.yaml', help='Path to configuration file')
@click.option('--verbose', '-v', is_flag=True, help='Enable verbose logging')
@click.pass_context
def cli(ctx, config, verbose):
    """Data Processing CLI Tool - Process and validate data files."""
    ctx.ensure_object(dict)
    ctx.obj['verbose'] = verbose

    if not os.path.exists(config):
        click.echo(f"Error: Config file {config} not found", err=True)
        sys.exit(1)

    ctx.obj['config'] = ConfigManager(config)

    if verbose:
        click.echo(f"Loaded config from {config}")

@cli.command()
@click.argument('input_file', type=click.Path(exists=True))
@click.option('--output', '-o', default='output.json', help='Output file path')
@click.option('--format', 'output_format', default='json', type=click.Choice(['json', 'csv', 'yaml']))
@click.pass_context
def transform(ctx, input_file, output, output_format):
    """Transform input data to specified output format."""
    config = ctx.obj['config']

    try:
        with open(input_file, 'r') as f:
            raw_data = yaml.safe_load(f)

        validated = validate_records(raw_data, config.get('validation', {}))

        if 'errors' in validated:
            click.echo(f"Validation failed: {validated['errors']}", err=True)
            sys.exit(1)

        formatted = format_output(validated, output_format)

        with open(output, 'w') as f:
            f.write(formatted)

        click.echo(f"Successfully transformed {input_file} -> {output}")

