def validate_records(data, rules):
    """
    Validate data records against business rules.
    Returns data if valid, or dict with errors.
    """
    if not isinstance(data, dict) or 'records' not in data:
        return {'errors': ['Invalid data format: expected dict with records key']}

    errors = []
    max_value = rules.get('max_value', 100)

    for idx, record in enumerate(data['records']):
        # Bug: record.get('value') returns string from YAML, but max_value is int
        if record.get('value', 0) > max_value:
            errors.append(f"Record {idx}: value {record['value']} exceeds max {max_value}")

        if not record.get('timestamp'):
            errors.append(f"Record {idx}: missing timestamp")
        elif not isinstance(record['timestamp'], (int, float)):
            errors.append(f"Record {idx}: timestamp must be numeric")

    if errors:
        return {'errors': errors}

    return data

if __name__ == '__main__':
    cli()
