import json
import csv
import io
from datetime import datetime, timezone
from typing import Dict, List, Any, Union

def format_output(data: Union[Dict, List], format_type: str) -> str:
    """Format data as JSON, CSV, or YAML string."""
    if format_type == 'json':
        return json.dumps(data, indent=2, default=str)
    elif format_type == 'yaml':
        import yaml
        return yaml.dump(data, default_flow_style=False)
    elif format_type == 'csv':
        return _to_csv(data)
    else:
        raise ValueError(f"Unsupported format: {format_type}")

def _to_csv(data: Union[Dict, List]) -> str:
    """Convert data to CSV format."""
    if isinstance(data, dict) and 'records' in data:
        records = data['records']
    elif isinstance(data, list):
        records = data
    else:
        raise ValueError("Data must contain records or be a list")

    if not records:
        return ""

    output = io.StringIO()
    writer = csv.DictWriter(output, fieldnames=records[0].keys())
    writer.writeheader()
    writer.writerows(records)
    return output.getvalue()

def timestamp_to_iso(timestamp: Union[int, float]) -> str:
    """Convert Unix timestamp to ISO format."""
    dt = datetime.fromtimestamp(timestamp, tz=timezone.utc)
    return dt.isoformat()

def sanitize_string(value: str) -> str:
    """Remove special characters and normalize whitespace."""
    return ' '.join(value.split())
