        return {
            'id': self.id,
            'username': self.username,
            'email': self.email,
            'created_at': self.created_at.isoformat(),
            'is_active': self.is_active
        }

@dataclass
class Session:
    id: str
    user_id: int
    created_at: datetime
    expires_at: datetime

class UserRepository:
    def __init__(self, database_url: str):
        self.database_url = database_url
        self._cache = {}

    def get_by_id(self, user_id: int) -> Optional[User]:
        # In production, this queries the database
        return self._cache.get(user_id)

    def get_by_email(self, email: str) -> Optional[User]:
        for user in self._cache.values():
            if user.email == email:
                return user
        return None

    def create(self, username: str, email: str) -> User:
        user_id = len(self._cache) + 1
        user = User(
            id=user_id,
            username=username,
            email=email,
            created_at=datetime.utcnow()
        )
        self._cache[user_id] = user
        return user

class SessionManager:
    def __init__(self, redis_url: str, ttl: int = 3600):
        self.redis_url = redis_url
        self.ttl = ttl
        self._sessions = {}

    def get_or_create(self, user_id: int) -> Session:
        for session in self._sessions.values():
            if session.user_id == user_id:
                return session
        return self._create_session(user_id)

    def _create_session(self, user_id: int) -> Session:
        session_id = str(uuid.uuid4())
        now = datetime.utcnow()
        session = Session(
            id=session_id,
            user_id=user_id,
            created_at=now,
            expires_at=datetime.fromtimestamp(now.timestamp() + self.ttl)
        )
        self._sessions[session_id] = session
        return session

    def invalidate(self, session_id: str) -> bool:
        if session_id in self._sessions:
            del self._sessions[session_id]
            return True
        return False
