        # Validate date format
        try:
            pd.to_datetime(df['date'])
        except Exception as e:
            errors.append(f"Date parsing error: {e}")

        # Check for negative amounts
        negative_sales = (df['amount'] < 0).sum()
        if negative_sales > 0:
            errors.append(f"Found {negative_sales} negative transaction amounts")

        # Check for extreme outliers (> 5 std from mean)
        if 'amount' in df.columns:
            mean = df['amount'].mean()
            std = df['amount'].std()
            outliers = df[df['amount'] > mean + (5 * std)]
            if len(outliers) > 0:
