import pandas as pd
import numpy as np
from scipy import stats

def regional_summary(df):
    """Generate summary statistics by region."""
    summary = df.groupby('region').agg({
        'amount': ['sum', 'mean', 'count'],
        'units_sold': 'sum'
    }).round(2)
    summary.columns = ['total_revenue', 'avg_transaction', 'transaction_count', 'total_units']
    return summary.sort_values('total_revenue', ascending=False)

def detect_anomalies(df, z_threshold=3):
    """Detect statistical anomalies using Z-score."""
    z_scores = np.abs(stats.zscore(df['amount'].dropna()))
    anomaly_indices = np.where(z_scores > z_threshold)[0]
    return df.iloc[anomaly_indices]

def category_performance(df):
