#!/usr/bin/env python3
"""Data validation utilities."""
import pandas as pd
from datetime import datetime

def check_nulls(df, columns):
    """Check for null values in specified columns."""
    issues = []
    for col in columns:
        null_count = df[col].isnull().sum()
        if null_count > 0:
            issues.append(f'{col}: {null_count} nulls')
    return issues

def check_date_range(df, date_col, start, end):
    """Validate dates fall within expected range."""
    out_of_range = df[(df[date_col] < start) | (df[date_col] > end)]
    return len(out_of_range)

def check_positive(df, columns):
    """Ensure numeric columns are positive."""
    issues = []
    for col in columns:
        negative_count = (df[col] < 0).sum()
        if negative_count > 0:
            issues.append(f'{col}: {negative_count} negative values')
    return issues

def validate_sales(df):
    """Run all validations on sales dataframe."""
    results = {
        'null_checks': check_nulls(df, ['transaction_id', 'date', 'product_id', 'total_amount']),
        'positive_checks': check_positive(df, ['quantity', 'unit_price', 'total_amount']),
        'row_count': len(df)
    }
    return results
