    users = data['users']
    issues = []

    for idx, user in enumerate(users):
        if not user.get('name'):
            issues.append(f"User {idx} missing name")
        if user.get('metadata') is None:
            issues.append(f"User {user.get('customer_id')} missing metadata")

    return issues, len(users)

