"""Data validation utilities."""

import pandas as pd
from typing import Dict, List, Tuple

def check_null_values(df: pd.DataFrame) -> Dict[str, int]:
    """Return count of nulls per column."""
    return df.isnull().sum().to_dict()

def check_duplicates(df: pd.DataFrame, key_cols: List[str]) -> int:
    """Return count of duplicate rows based on key columns."""
    return df.duplicated(subset=key_cols).sum()

def validate_numeric_range(df: pd.DataFrame, col: str, min_val: float, max_val: float) -> Tuple[int, pd.DataFrame]:
    """Check if values fall within expected range."""
    out_of_range = df[(df[col] < min_val) | (df[col] > max_val)]
    return len(out_of_range), out_of_range

def validate_date_format(df: pd.DataFrame, col: str, fmt: str = '%Y-%m-%d') -> List[str]:
    """Return list of invalid date strings."""
    invalid = []
    for val in df[col].unique():
        try:
            pd.to_datetime(val, format=fmt)
        except:
            invalid.append(val)
    return invalid
