"""Data validation utilities for the sales pipeline."""
import csv
import json
import sys
from datetime import datetime
from typing import List, Dict, Any, Tuple


def load_csv(filepath: str) -> List[Dict[str, Any]]:
    """Load CSV file and return list of dictionaries."""
    with open(filepath, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        return list(reader)


def validate_not_null(records: List[Dict], columns: List[str]) -> List[Tuple[int, str, str]]:
    """Check for null/empty values in specified columns."""
    errors = []
    for idx, record in enumerate(records, start=2):  # Row 2 is first data row
        for col in columns:
            if not record.get(col) or record[col].strip() == '':
                errors.append((idx, col, 'NULL_VALUE'))
    return errors


def validate_positive(records: List[Dict], columns: List[str]) -> List[Tuple[int, str, str]]:
    """Ensure numeric columns have positive values."""
    errors = []
    for idx, record in enumerate(records, start=2):
        for col in columns:
            try:
                val = float(record.get(col, 0))
                if val <= 0:
                    errors.append((idx, col, f'NON_POSITIVE: {val}'))
            except ValueError:
                errors.append((idx, col, f'INVALID_NUMBER: {record.get(col)}'))
    return errors


def validate_date_format(records: List[Dict], column: str, fmt: str = '%Y-%m-%d') -> List[Tuple[int, str, str]]:
    """Validate date column matches expected format."""
    errors = []
    for idx, record in enumerate(records, start=2):
        try:
            datetime.strptime(record.get(column, ''), fmt)
        except ValueError:
            errors.append((idx, column, f'INVALID_DATE: {record.get(column)}'))
    return errors


def main(filepath: str):
    print(f"Validating: {filepath}")
    records = load_csv(filepath)
