import pandas as pd
import yaml
import sys
from pathlib import Path

def validate_schema(df, schema_config):
    """Validate dataframe against schema definition."""
    errors = []

    for col, dtype in schema_config.items():
        if col not in df.columns:
            errors.append(f"Missing required column: {col}")
            continue

        if dtype == 'float' and not pd.api.types.is_float_dtype(df[col]):
            errors.append(f"Column {col} should be float, got {df[col].dtype}")
        elif dtype == 'int' and not pd.api.types.is_integer_dtype(df[col]):
            errors.append(f"Column {col} should be int, got {df[col].dtype}")

    return errors

def check_data_quality(df, rules):
    """Apply data quality checks."""
    issues = []

    for rule in rules:
        col = rule['column']
        rule_type = rule['rule']

        if rule_type == 'non_negative':
            invalid = df[df[col] < 0]
            if len(invalid) > 0:
                issues.append(f"Found {len(invalid)} negative values in {col}")
        elif rule_type == 'positive_integer':
            invalid = df[df[col] <= 0]
            if len(invalid) > 0:
