#!/usr/bin/env python3
"""Data validation utilities for the analysis pipeline."""

import csv
import sys
from pathlib import Path

def validate_csv_schema(filepath, required_columns):
    """Check that CSV has all required columns."""
    with open(filepath, 'r') as f:
        reader = csv.DictReader(f)
        headers = reader.fieldnames
        missing = set(required_columns) - set(headers)
        if missing:
            return False, f"Missing columns: {missing}"
        return True, "Schema valid"

def check_nulls(filepath):
    """Report any null/empty values in CSV."""
    issues = []
    with open(filepath, 'r') as f:
        reader = csv.DictReader(f)
        for i, row in enumerate(reader, start=2):
            for col, val in row.items():
                if not val or val.strip() == '':
                    issues.append(f"Row {i}, column '{col}': empty value")
    return issues

if __name__ == '__main__':
    if len(sys.argv) < 2:
        print("Usage: validate.py <csv_file>")
        sys.exit(1)

    filepath = Path(sys.argv[1])
    nulls = check_nulls(filepath)
    if nulls:
        print(f"Found {len(nulls)} issues:")
