#!/usr/bin/env python3
"""Data validation checks for sales pipeline."""

import pandas as pd
from pathlib import Path

def check_nulls(df: pd.DataFrame, critical_cols: list) -> dict:
    """Check for null values in critical columns."""
    results = {}
    for col in critical_cols:
        null_count = df[col].isna().sum()
        results[col] = {'null_count': int(null_count), 'passed': null_count == 0}
    return results

def check_value_ranges(df: pd.DataFrame) -> dict:
    """Validate numeric values are within expected ranges."""
    checks = {
        'quantity_positive': (df['quantity'] > 0).all(),
        'price_positive': (df['unit_price'] > 0).all(),
        'discount_valid': ((df['discount_pct'] >= 0) & (df['discount_pct'] <= 1)).all()
    }
    return checks

def check_referential_integrity(sales_df: pd.DataFrame, customers_df: pd.DataFrame) -> dict:
    """Verify all customer_ids in sales exist in customers table."""
    sales_customers = set(sales_df['customer_id'].unique())
    known_customers = set(customers_df['customer_id'].unique())
    orphans = sales_customers - known_customers
    return {'orphan_customers': list(orphans), 'passed': len(orphans) == 0}

if __name__ == '__main__':
