// src/middleware/rateLimiter.ts - New file

import Redis from 'ioredis';
import { Request, Response, NextFunction } from 'express';

interface RateLimiterOptions {
  windowMs: number;
  maxRequests: number;
  keyPrefix: string;
  strategy: 'ip' | 'user' | 'combined';
}

export class RateLimiter {
  private redis: Redis;
  private options: RateLimiterOptions;

  constructor(options: RateLimiterOptions) {
    this.options = options;
    this.redis = new Redis(process.env.REDIS_URL || 'redis://localhost:6379');
  }

  private getKey(req: Request): string {
    const { keyPrefix, strategy } = this.options;

    switch (strategy) {
      case 'ip':
        return `${keyPrefix}${req.ip}`;
      case 'user':
        return `${keyPrefix}${req.user?.id || req.ip}`;
      case 'combined':
        return `${keyPrefix}${req.ip}:${req.user?.id || 'anon'}`;
      default:
        return `${keyPrefix}${req.ip}`;
    }
  }

  middleware() {
    return async (req: Request, res: Response, next: NextFunction) => {
      const key = this.getKey(req);
      const { windowMs, maxRequests } = this.options;

      try {
        const current = await this.redis.incr(key);

        if (current === 1) {
          await this.redis.pexpire(key, windowMs);
        }

        res.setHeader('X-RateLimit-Limit', maxRequests);
        res.setHeader('X-RateLimit-Remaining', Math.max(0, maxRequests - current));

        if (current > maxRequests) {
          const ttl = await this.redis.pttl(key);
          res.setHeader('Retry-After', Math.ceil(ttl / 1000));
          return res.status(429).json({
            error: 'Too many requests',
            retryAfter: Math.ceil(ttl / 1000)
          });
        }

        next();
      } catch (error) {
        console.error('Rate limiter error:', error);
        // Fail open - allow request if Redis is down
        next();
      }
    };
  }
}
