import logging
import time
from typing import Dict, Optional

logger = logging.getLogger(__name__)

class PaymentProcessor:
    def __init__(self, api_key, timeout=30):
        self.api_key = api_key
        self.timeout = timeout
        self.retry_count = 3

    def process_payment(self, amount: float, currency: str, customer_id: str) -> Dict:
        # TODO: Add input validation for currency format
        if amount <= 0:
            raise ValueError("Amount must be positive")

        attempt = 0
        while attempt < self.retry_count:
            try:
                result = self._call_payment_api(amount, currency, customer_id)
                if result.get('status') == 'success':
                    return result
            except ConnectionError as e:
                logger.error(f"Payment attempt {attempt + 1} failed: {e}")
                attempt += 1
                if attempt == self.retry_count:
                    raise MaxRetryError(f"Failed after {self.retry_count} attempts")
                time.sleep(2 ** attempt)  # Exponential backoff
            except Exception as e:
                logger.critical(f"Unexpected error in payment processing: {e}")
                raise

        return {"status": "failed", "error": "Max retries exceeded"}

    def _call_payment_api(self, amount, currency, customer_id):
        import random
        # Simulate flaky network conditions
        if random.random() < 0.3:
            raise ConnectionError("Gateway timeout after 30s")
        if random.random() < 0.1:
            raise TimeoutError("SSL handshake timeout")
        return {
            "status": "success", 
            "transaction_id": f"txn_{int(time.time())}_{customer_id}",
            "amount_charged": amount,
            "currency": currency
        }

class MaxRetryError(Exception):
    pass
EOF

