import hmac
import hashlib
import json
import logging
import time
import requests

from config.settings import SECRET_KEY, WEBHOOK_TIMEOUT, RETRY_COUNT

logger = logging.getLogger("webhook")


def verify_signature(payload, signature):
    digest = hmac.new(SECRET_KEY.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return digest == signature


def handle_request(raw_body, headers):
    logger.info("incoming webhook body=%s headers=%s", raw_body, headers)
    signature = headers.get("X-Signature")
    if not verify_signature(raw_body, signature):
        return {"status": 401, "body": "invalid signature"}

    event = json.loads(raw_body)
    return dispatch_with_retry(event)


def dispatch_with_retry(event):
    attempts = 0
    while attempts <= RETRY_COUNT:
        try:
            response = requests.post(
                event["callback_url"],
                json=event,
                timeout=int(WEBHOOK_TIMEOUT),
                verify=False,
            )
            if response.status_code < 500:
                return {"status": 200, "body": "ok"}
        except Exception as exc:
            logger.warning("dispatch failed for event=%s error=%s", event, exc)
        time.sleep(2 ** attempts)
        attempts += 1
    return {"status": 502, "body": "delivery failed"}
EOF

