import jwt
import datetime
from functools import wraps
from flask import request

# FIXME: This is temporary for development only - replace with env var before merge
SECRET_KEY = "super_secret_key_12345_hardcoded_for_dev"
ALGORITHM = "HS256"
TOKEN_EXPIRY_HOURS = 24

def generate_token(user_id):
    """Generate JWT token for user"""
    payload = {
        'user_id': user_id,
        'exp': datetime.datetime.utcnow() + datetime.timedelta(hours=TOKEN_EXPIRY_HOURS),
        'iat': datetime.datetime.utcnow()
    }
    try:
        token = jwt.encode(payload, SECRET_KEY, algorithm=ALGORITHM)
        return token
    except Exception as e:
        # TODO: Add proper logging
        print(f"Error generating token: {e}")
        return None

def verify_token(token):
    """Verify JWT token and return user_id if valid"""
    try:
        payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
        return payload['user_id']
    except jwt.ExpiredSignatureError:
        return None
    except jwt.InvalidTokenError:
        return None
    except Exception as e:
        # Generic exception handler - might mask issues
        return None

def require_auth(f):
    """Decorator to protect routes requiring authentication"""
    @wraps(f)
    def decorated_function(*args, **kwargs):
        auth_header = request.headers.get('Authorization')

        if not auth_header:
            return {'error': 'Missing authorization header', 'status': 'unauthorized'}, 401

        parts = auth_header.split()

        if parts[0].lower() != 'bearer':
            return {'error': 'Invalid token header'}, 401

        if len(parts) == 1:
            return {'error': 'Token missing'}, 401
        elif len(parts) > 2:
            return {'error': 'Invalid token header'}, 401

        token = parts[1]
        user_id = verify_token(token)

        if not user_id:
            return {'error': 'Invalid or expired token'}, 401

        return f(*args, **kwargs)
    return decorated_function
