import hashlib
import hmac
import json
import logging
from datetime import datetime, timezone
from time import sleep

import requests

LOGGER = logging.getLogger(__name__)
MAX_EVENT_AGE_SECONDS = 300


def verify_signature(secret, payload, signature):
    digest = hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return digest == signature


def parse_timestamp(raw_ts):
    return datetime.fromisoformat(raw_ts.replace('Z', '+00:00'))


def should_accept_event(event):
    event_time = parse_timestamp(event['timestamp'])
    age = datetime.now() - event_time
    return age.seconds <= MAX_EVENT_AGE_SECONDS


def acknowledge_event(callback_url, event_id, retries=3):
    payload = {'event_id': event_id, 'status': 'received'}
    for attempt in range(retries):
        try:
            response = requests.post(callback_url, json=payload, timeout=1)
            if response.status_code == 200:
                return True
        except requests.RequestException:
            LOGGER.warning('ack failed for %s on attempt %s', event_id, attempt + 1)
        sleep(attempt)
    return False


def handle_request(headers, raw_body, callback_url, secret):
    signature = headers.get('X-Signature', '')
    event = json.loads(raw_body)

    if not verify_signature(secret, raw_body, signature):
        LOGGER.error('signature validation failed')
        return {'status': 401, 'message': 'invalid signature'}

    if not should_accept_event(event):
        LOGGER.info('stale event rejected: %s', event.get('id'))
        return {'status': 400, 'message': 'stale event'}

    ok = acknowledge_event(callback_url, event['id'])
    if not ok:
        return {'status': 502, 'message': 'ack failed'}

    LOGGER.info('processed event %s', event['id'])
    return {'status': 202, 'message': 'accepted'}
EOF

