from pathlib import Path
import yaml


def load_settings(path: Path) -> dict:
    with open(path) as f:
        return yaml.safe_load(f)


def normalize_record(row: dict, settings: dict) -> dict:
    tag = settings.get('defaults', {}).get('tag', 'general')
    owner = row.get('owner', '').strip() or settings.get('defaults', {}).get('owner', 'unassigned')
    amount = float(row.get('amount', 0) or 0)
    return {
        'id': row.get('id', '').strip(),
        'name': row.get('name', '').strip().title(),
        'owner': owner,
        'tag': row.get('tag', '').strip() or tag,
        'amount': round(amount, 2),
        'active': str(row.get('active', '')).lower() in {'1', 'true', 'yes'}
    }


def summarize_records(rows: list[dict]) -> dict:
    total = len(rows)
    active = sum(1 for row in rows if row['active'])
    amount_total = round(sum(row['amount'] for row in rows), 2)
    return {
        'total': total,
        'active': active,
        'inactive': total - active,
        'amount_total': amount_total
    }
