class DataProcessor:
    def __init__(self, config_path):
        self.config = self._load_config(config_path)
        self.preferences_file = Path(self.config.get('preferences_path', 'user_prefs.json'))

    def _load_config(self, path):
        with open(path) as f:
            return json.load(f)

    def save_user_preference(self, key, value, context=None):
        """Store user preference for future sessions."""
        prefs = self._load_preferences()
        prefs[key] = {
            'value': value,
            'set_at': datetime.now().isoformat(),
            'context': context
        }
        self._save_preferences(prefs)
        logger.info(f'Saved preference: {key}')

    def _load_preferences(self):
        if self.preferences_file.exists():
            with open(self.preferences_file) as f:
                return json.load(f)
        return {}

    def _save_preferences(self, prefs):
        with open(self.preferences_file, 'w') as f:
            json.dump(prefs, f, indent=2)

    def get_preference(self, key, default=None):
        prefs = self._load_preferences()
        if key in prefs:
            return prefs[key]['value']
        return default

    def process_batch(self, data_file):
        """Process data according to stored preferences."""
        auto_approve = self.get_preference('auto_approve_actions', False)
        default_action = self.get_preference('default_action', 'review')

        with open(data_file) as f:
            data = json.load(f)

        results = []
        for item in data:
            if auto_approve or default_action == 'execute':
                results.append(self._execute_item(item))
            else:
                results.append(self._queue_for_review(item))
        return results
