from datetime import datetime, timedelta

class MemoryStore:
    """Persistent memory for storing session state and learned behaviors."""

    def __init__(self, storage_path='memory.json'):
        self.storage_path = Path(storage_path)
        self.memory = self._load()

    def _load(self):
        if self.storage_path.exists():
            with open(self.storage_path) as f:
                return json.load(f)
        return {'facts': {}, 'triggers': [], 'session_history': []}

    def save(self):
        with open(self.storage_path, 'w') as f:
            json.dump(self.memory, f, indent=2)

    def remember(self, key, value, expires_in_days=None):
        """Store a fact with optional expiration."""
        entry = {
            'value': value,
            'stored_at': datetime.now().isoformat()
        }
        if expires_in_days:
            expires = datetime.now() + timedelta(days=expires_in_days)
            entry['expires_at'] = expires.isoformat()
        self.memory['facts'][key] = entry
        self.save()

    def recall(self, key):
        """Retrieve a stored fact if not expired."""
        if key not in self.memory['facts']:
            return None
        entry = self.memory['facts'][key]
        if 'expires_at' in entry:
            if datetime.fromisoformat(entry['expires_at']) < datetime.now():
                del self.memory['facts'][key]
                self.save()
                return None
        return entry['value']

    def add_trigger(self, condition, action, description):
        """Add a conditional trigger for future activation."""
        self.memory['triggers'].append({
            'condition': condition,
            'action': action,
            'description': description,
            'created_at': datetime.now().isoformat(),
            'activated': False
        })
        self.save()

    def check_triggers(self, context):
        """Check and execute any matching triggers."""
        for trigger in self.memory['triggers']:
            if not trigger['activated'] and self._eval_condition(trigger['condition'], context):
                trigger['activated'] = True
                self.save()
                return trigger['action']
        return None
