import os
import resource
import sys
import yaml
from restrictedpython import compile_restricted, safe_globals

class SandboxExecutor:
    def __init__(self, config_path):
        self.config = self._load_config(config_path)

    def _load_config(self, path):
        with open(path) as f:
            return yaml.safe_load(f)

    def execute(self, code, job_id):
        limits = self.config['sandbox']['resources']
        resource.setrlimit(resource.RLIMIT_AS, 
                          (limits['memory_limit_mb'] * 1024 * 1024, -1))

        if self.config['sandbox']['network']['mode'] == 'restricted':
            raise PermissionError(f"Network access denied by policy for job {job_id}")

        byte_code = compile_restricted(code, '<inline>', 'exec')
        exec(byte_code, safe_globals, {})

if __name__ == '__main__':
