import hashlib
import mimetypes
from pathlib import Path
from typing import Dict, List, Optional

def get_file_hash(filepath: str, algorithm: str = 'md5') -> str:
    """Calculate hash of a file"""
    hash_func = hashlib.new(algorithm)
    with open(filepath, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            hash_func.update(chunk)
    return hash_func.hexdigest()

def detect_file_type(filepath: str) -> Optional[str]:
    """Detect MIME type of a file"""
    mime_type, _ = mimetypes.guess_type(filepath)
    return mime_type

def group_files_by_extension(filepaths: List[str]) -> Dict[str, List[str]]:
    """Group a list of file paths by their extension"""
    groups = {}
    for fp in filepaths:
        ext = Path(fp).suffix.lower() or '.no_extension'
        groups.setdefault(ext, []).append(fp)
    return groups

def format_file_size(size_bytes: int) -> str:
    """Convert bytes to human readable format"""
    for unit in ['B', 'KB', 'MB', 'GB']:
        if size_bytes < 1024:
            return f'{size_bytes:.1f} {unit}'
        size_bytes /= 1024
    return f'{size_bytes:.1f} TB'
