cat > /tmp/server/etc/nginx.conf <<'EOF'
user www-data;
worker_processes auto;
pid /run/nginx.pid;

events {
    worker_connections 1024;
}

http {
    include       mime.types;
    default_type  application/octet-stream;
    sendfile      on;
    keepalive_timeout 65;

    upstream inventory_api {
        server 127.0.0.1:8080;
        keepalive 32;
    }

    server {
        listen 80;
        server_name _;

        access_log /tmp/server/var/log/app/access.log;
        error_log /tmp/server/var/log/app/error.log warn;

        location /health {
            proxy_pass http://inventory_api/health;
        }

        location / {
            proxy_set_header Host $host;
            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
            proxy_pass http://inventory_api;
        }
    }
}
EOF

