from pathlib import Path
import json

BOOKMARKS = Path('/tmp/research/bookmarks.json')


def load_bookmarks(path: Path):
    return json.loads(path.read_text())


def normalize(items):
    normalized = []
    for item in items:
        url = item['url'].rstrip('/')
        normalized.append({
            **item,
            'url': url,
            'domain': url.split('/')[2]
        })
    return normalized


if __name__ == '__main__':
    items = load_bookmarks(BOOKMARKS)
    print(json.dumps(normalize(items), indent=2))
EOF

