        super().__init__()
        self.links = []

    def handle_starttag(self, tag, attrs):
        if tag == 'a':
            attr_map = dict(attrs)
            href = attr_map.get('href')
            if href:
                self.links.append(href)


def main():
    if len(sys.argv) != 2:
        print('Usage: parse_links.py <html-file>', file=sys.stderr)
        sys.exit(1)

    html_path = Path(sys.argv[1])
    data = html_path.read_text(encoding='utf-8', errors='ignore')
    parser = LinkParser()
    parser.feed(data)

    for i, link in enumerate(parser.links[:50], start=1):
        print(f'{i:02d}: {link}')

    print(f'Total links found: {len(parser.links)}')

if __name__ == '__main__':
    main()
EOF

