import requests
from bs4 import BeautifulSoup
import json
import sys

def fetch_blog_posts(url):
    """Fetch and parse blog posts from a URL.

    This is a basic implementation - doesn't handle JavaScript rendering,
    rate limiting, or complex page structures well.
    """
    try:
        response = requests.get(url, timeout=15)
        response.raise_for_status()
        soup = BeautifulSoup(response.text, 'html.parser')

        # Generic extraction - works for simple blogs
        articles = []
        for article in soup.find_all('article')[:5]:
            title = article.find(['h1', 'h2', 'h3'])
            link = article.find('a')
            articles.append({
                'title': title.text.strip() if title else 'No title',
                'link': link.get('href') if link else None
            })

        return {'status': 'success', 'articles': articles}
    except Exception as e:
        return {'status': 'error', 'message': str(e)}

if __name__ == '__main__':
    if len(sys.argv) < 2:
        print(json.dumps({'error': 'URL required'}))
        sys.exit(1)

    result = fetch_blog_posts(sys.argv[1])
    print(json.dumps(result, indent=2))
EOF

