#!/usr/bin/env python3
from html.parser import HTMLParser
from pathlib import Path
import json

BASE = Path('/tmp/research/downloads')

class TitleParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.in_title = False
        self.title = []

    def handle_starttag(self, tag, attrs):
        if tag.lower() == 'title':
            self.in_title = True

    def handle_endtag(self, tag):
        if tag.lower() == 'title':
            self.in_title = False

    def handle_data(self, data):
        if self.in_title:
            self.title.append(data.strip())

results = []
for file in sorted(BASE.glob('*.html')):
    parser = TitleParser()
    parser.feed(file.read_text(errors='ignore'))
    title = ' '.join(x for x in parser.title if x)
    results.append({
        'file': file.name,
        'title': title or None,
        'size_bytes': file.stat().st_size
    })

print(json.dumps(results, indent=2))
EOF
